package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceDocumentExpiryController;import com.rpb.reservation.workforce.documents.expiry.*;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
@WebMvcTest(WorkforceDocumentExpiryController.class) @Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class}) @ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforceDocumentExpiryLocalRuntimeSecurityTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean DocumentExpiryService service;@MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 @Test void onlyGetReminderRouteIsAllowed()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));String path="/api/v1/stores/"+UUID.randomUUID()+"/workforce/document-expiries";mvc.perform(get(path)).andExpect(status().isOk());verify(service).list(any(),any(),eq(30),eq("all"),eq(50),eq(0));mvc.perform(post(path)).andExpect(status().isForbidden());mvc.perform(put(path).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(delete(path)).andExpect(status().isForbidden());}
 @Test void employeeBatchRouteAllowsOnlyScopedRead()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));var id=UUID.randomUUID();String path="/api/v1/stores/"+UUID.randomUUID()+"/workforce/document-expiries/employees";mvc.perform(get(path+"?employeeIds="+id)).andExpect(status().isOk());verify(service).employeeCounts(any(),any(),eq(30),eq(List.of(id)));mvc.perform(post(path)).andExpect(status().isForbidden());mvc.perform(put(path).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isForbidden());}
}
